import 'package:flutter/material.dart';
import '../models/match.dart';
class MatchSetupScreen extends StatefulWidget{const MatchSetupScreen({super.key});@override State<MatchSetupScreen> createState()=>_MatchSetupScreenState();}
class _MatchSetupScreenState extends State<MatchSetupScreen>{final h=TextEditingController(),a=TextEditingController();@override void dispose(){h.dispose();a.dispose();super.dispose();}void create(){if(h.text.trim().isEmpty||a.text.trim().isEmpty){ScaffoldMessenger.of(context).showSnackBar(const SnackBar(content:Text('Enter both team names.')));return;}Navigator.pop(context,RugbyMatch(id:DateTime.now().microsecondsSinceEpoch.toString(),homeTeam:h.text.trim(),awayTeam:a.text.trim(),createdAt:DateTime.now()));}
@override Widget build(BuildContext c)=>Scaffold(appBar:AppBar(title:const Text('New match')),body:ListView(padding:const EdgeInsets.all(20),children:[const Text('Team setup',style:TextStyle(fontSize:28,fontWeight:FontWeight.bold)),const SizedBox(height:25),TextField(controller:h,decoration:const InputDecoration(labelText:'Home team',border:OutlineInputBorder())),const SizedBox(height:16),TextField(controller:a,decoration:const InputDecoration(labelText:'Away team',border:OutlineInputBorder())),const SizedBox(height:25),FilledButton.icon(onPressed:create,icon:const Icon(Icons.play_arrow),label:const Padding(padding:EdgeInsets.all(14),child:Text('Start match')))]));}
